sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {
	var url = gs.getProperty("glide.servlet.uri") + "services?id=hoc_hrm_ticket_page&table=x_hccc_hoc_ohs_investigation_case&sys_id=" + current.sys_id;
	var lable="Ouvrir le dossier";
	template.print("<a title="+'link'+" href='"+url+"'"+"target="+'_blank'+" rel="+'noopener'+"><button>"+lable+"</button></a>" );



	})(current, template, email, email_action, event);
